-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromeCLFactory.json. Do not edit: change the chain file or ABI and regenerate.
-- TickSpacingEnabled(int24,uint24)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_cl_factory__tick_spacing_enabled',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    toInt32(reinterpretAsInt256(reverse(unhex(substring(topic1, 3, 64))))) as tick_spacing,
    toUInt32(reinterpretAsUInt256(reverse(unhex(substring(topic2, 3, 64))))) as fee
from {{ source('chain_base', 'logs') }}
where topic0 = '0xebafae466a4a780a1d87f5fab2f52fad33be9151a7f69d099e8934c8de85b747'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_cl_factory')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
